function Esc($s){[Security.SecurityElement]::Escape([string]$s)}
function Plain($s){$s=[regex]::Replace($s,'!?\[([^\]]*)\]\(([^)]+)\)','$1 ($2)');$s=$s.Replace('**','').Replace('`','');return $s}
function P($text,$style='Normal'){[void]$body.Append('<w:p><w:pPr><w:pStyle w:val="'+$style+'"/></w:pPr><w:r><w:t xml:space="preserve">'+(Esc (Plain $text))+'</w:t></w:r></w:p>')}
function AddHeading($text,$level=1){P $text ('Heading'+$level)}
function Table($lines){
 $script:tables[$script:chapter]++;P ('Bảng '+$script:chapter+'.'+$script:tables[$script:chapter]+'. '+$script:currentHeading) 'TableCaption'
 [void]$body.Append('<w:tbl><w:tblPr><w:tblW w:w="9071" w:type="dxa"/><w:tblBorders><w:top w:val="single" w:sz="4"/><w:left w:val="single" w:sz="4"/><w:bottom w:val="single" w:sz="4"/><w:right w:val="single" w:sz="4"/><w:insideH w:val="single" w:sz="4"/><w:insideV w:val="single" w:sz="4"/></w:tblBorders></w:tblPr>');$row=0
 foreach($line in $lines){if($line -match '^\s*\|?[\s:|\-]+\|?\s*$'){continue};$cells=$line.Trim().Trim('|').Split('|');[void]$body.Append('<w:tr>');if($row -eq 0){[void]$body.Append('<w:trPr><w:tblHeader/></w:trPr>')};foreach($cell in $cells){[void]$body.Append('<w:tc><w:tcPr><w:tcW w:w="'+[int](9071/$cells.Count)+'" w:type="dxa"/></w:tcPr><w:p><w:pPr><w:pStyle w:val="TableText"/></w:pPr><w:r>');if($row -eq 0){[void]$body.Append('<w:rPr><w:b/></w:rPr>')};[void]$body.Append('<w:t xml:space="preserve">'+(Esc (Plain $cell.Trim()))+'</w:t></w:r></w:p></w:tc>')};[void]$body.Append('</w:tr>');$row++};[void]$body.Append('</w:tbl>');P ''
}
function AppendMarkdown($text,$prefix){
 foreach($m in [regex]::Matches($text,'https?://[^\s)<>]+')){[void]$urls.Add($m.Value.TrimEnd('.',';',','))}
 $lines=$text -split "`r?`n";$i=0;$n=0;$sub=0;$code=$false
 while($i -lt $lines.Count){$line=$lines[$i];$i++
  if($line -match '^```'){$code=!$code;continue};if($code){if($line.Trim()){P $line 'Code'};continue}
  if($line -match '^\s*\|'){ $rows=@($line);while($i -lt $lines.Count -and $lines[$i] -match '^\s*\|'){$rows+=$lines[$i];$i++};Table $rows;continue}
  if($line -match '^(#{1,4})\s+(.+)$'){$depth=$Matches[1].Length;if($depth -eq 1){continue};$title=$Matches[2] -replace '^\d+(?:\.[A-Za-z0-9]+)*\.?\s*','';if($depth -eq 2){$n++;$sub=0;$number=$prefix+'.'+$n}else{$sub++;$number=$prefix+'.'+$n+'.'+$sub};$script:currentHeading=$title;AddHeading ($number+'. '+$title) ([Math]::Min(3,($number.Split('.').Count)));continue}
  if(!$line.Trim() -or $line -match '^---+$|^!\['){continue};P $line
 }
}
