function WriteXml($p,$s){[xml]$verify=$s;[IO.File]::WriteAllText((Join-Path $stage $p),$s,$utf8)}
WriteXml 'word/document.xml' $doc;WriteXml 'word/styles.xml' $styles;WriteXml 'word/settings.xml' '<w:settings xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:updateFields w:val="true"/></w:settings>'
WriteXml 'word/_rels/document.xml.rels' ('<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'+($rels -join '')+'</Relationships>')
WriteXml '_rels/.rels' '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="doc" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>'
WriteXml '[Content_Types].xml' '<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Default Extension="png" ContentType="image/png"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/><Override PartName="/word/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.styles+xml"/><Override PartName="/word/settings.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.settings+xml"/></Types>'
$output="$root\docs\M1-M3_BaoCaoTongHop.docx";if(Test-Path -LiteralPath $output){Move-Item -LiteralPath $output -Destination ($output+'.previous-'+[DateTimeOffset]::UtcNow.ToString('yyyyMMddTHHmmssfffZ'))}
[IO.Compression.ZipFile]::CreateFromDirectory($stage,$output)
if(!$stage.StartsWith($root+'\temp\docx-')){throw 'Unsafe cleanup path'};Remove-Item -LiteralPath $stage -Recurse -Force
[pscustomobject]@{output=$output;images=$script:img;tables=($script:tables.Values|Measure-Object -Sum).Sum;references=$urls.Count}|ConvertTo-Json -Compress
